-- 삼키지 않고 다시 던진다

public <T> T execute(String message, TraceCallback<T> callback) {
    TraceStatus status = null;
    try {
        status = trace.begin(message);
        T result = callback.call();
        trace.end(status);
        return result;
    } catch (Exception e) {
        trace.exception(status, e);
        throw new RuntimeException(e);        // 감싸서 던진다
    }
}

